DELETE FROM LEAVE_REQUEST
WHERE LEAVE_ID = #{leaveId}
  AND EMPNO    = #{empno}
  AND STATUS   = 'PENDING'

mapper.update:
UPDATE LEAVE_BALANCE
SET USED_DAYS = USED_DAYS + #{days}
WHERE EMPNO = #{empno} AND YEAR = #{year}

UPDATE LEAVE_BALANCE
SET USED_DAYS = GREATEST(0, USED_DAYS - #{days})
WHERE EMPNO = #{empno} AND YEAR = #{year}
